___CSS_LOADER_EXPORT___.push([module.id, `/* ---------------------------------------------------------------------
   Homepage V2: a Rubik's cube of light over the holo platform, on the
   same black as the About and Art pages.
   --------------------------------------------------------------------- */
/* nothing scrolls on this page: lock it, so turning the cube on a phone
   never drags or pull-to-refreshes the page (iOS) */
html.home-v2-html,
body.home-v2-body {
  height: 100%;
  overflow: hidden;
  overscroll-behavior: none;
}

body.home-v2-body {
  position: fixed;
  inset: 0;
  background: #000;
}

.home-v2 {
  --rc-size: min(38vmin, 340px);
  --home-cyan: #00bff3;
  --home-holo: #6ff5ee;
  --home-font: "DINWeb", "Lucida Grande", verdana, sans-serif;
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  background: linear-gradient(170deg, #03050a 0%, #000 55%, #02050b 100%);
  color: #ccd4de;
  font-family: var(--home-font);
  overflow: hidden;
  touch-action: none;
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}

/* --- name ---------------------------------------------------------- */
.home-v2-header {
  flex: 0 0 auto;
  padding-top: 64px;
  text-align: center;
}

.home-v2 .home-v2-name {
  margin: 0;
  /* the trailing letter-spacing would push the name off centre */
  padding-left: 0.55em;
  color: #dff4ff;
  font: 600 clamp(18px, 2.4vw, 30px) / 1 var(--home-font);
  letter-spacing: 0.55em;
  white-space: nowrap;
}

.flash-letter {
  display: inline-block;
  opacity: 0;
  /* strike on (delay set per letter), then, once every letter is lit, a
     glow runs through the name from left to right, one letter at a time */
  animation:
    flash-on 1000ms linear var(--flash-delay, 0ms) both,
    name-glow 5s ease-in-out var(--glow-delay, 2800ms) infinite;
}

.flash-space {
  display: inline-block;
  width: 0.5em;
}

@keyframes name-glow {
  0%,
  12%,
  100% {
    color: #dff4ff;
    text-shadow: 0 0 10px rgba(0, 191, 243, 0.35);
  }
  5% {
    color: #fff;
    text-shadow: 0 0 12px #6ff5ee, 0 0 28px #00bff3, 0 0 44px rgba(0, 191, 243, 0.6);
  }
}

/* a tube light striking: bright flash, flicker, then steady */
@keyframes flash-on {
  0% {
    opacity: 0;
  }
  6% {
    opacity: 1;
    color: #fff;
    text-shadow: 0 0 16px #6ff5ee, 0 0 34px #00bff3;
  }
  13% {
    opacity: 0.1;
  }
  22% {
    opacity: 1;
    color: #fff;
    text-shadow: 0 0 12px #6ff5ee;
  }
  30% {
    opacity: 0.35;
  }
  40% {
    opacity: 1;
    color: #fff;
    text-shadow: 0 0 14px #6ff5ee, 0 0 26px #00bff3;
  }
  100% {
    opacity: 1;
    color: #dff4ff;
    text-shadow: 0 0 10px rgba(0, 191, 243, 0.35);
  }
}

.home-v2 .home-v2-tagline {
  margin: 16px 0 0;
  padding-left: 0.4em;
  color: var(--home-cyan);
  font: 600 11px/1 var(--home-font);
  letter-spacing: 0.4em;
  text-transform: uppercase;
  animation: home-fade-in 800ms ease-out 1.8s both;
}

@keyframes home-fade-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* --- stage ---------------------------------------------------------- */
.home-v2-stage {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding-bottom: 56px;
}

.home-v2-float {
  position: relative;
  z-index: 1;
  animation: home-bob 6s ease-in-out infinite;
}

@keyframes home-bob {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}

/* room around the cube to grab it, and for its corners as it turns */
.rc-scene {
  position: relative;
  display: grid;
  place-items: center;
  width: calc(var(--rc-size) * 1.75);
  height: calc(var(--rc-size) * 1.75);
  perspective: 1500px;
  cursor: grab;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

.rc-scene.is-dragging {
  cursor: grabbing;
}

.rc-squash {
  width: var(--rc-size);
  height: var(--rc-size);
  transform-style: preserve-3d;
}

.rc-cube {
  --rc-half: calc(var(--rc-size) / 2);
  position: relative;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  will-change: transform;
}

.rc-face {
  position: absolute;
  inset: 0;
  display: grid;
  /* equal squares even when a link's name is wider than its square */
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-template-rows: repeat(3, minmax(0, 1fr));
  gap: 4%;
  padding: 4%;
  box-sizing: border-box;
  background: rgba(2, 7, 15, 0.9);
  box-shadow: inset 0 0 0 1px rgba(111, 245, 238, 0.16);
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  /* each face is one flat layer: Safari otherwise places its squares, name
     and hologram in 3D on their own, so back faces show through and the
     hologram can land over the name */
  transform-style: flat;
}

/* every square: same dark colour, only its edges glow */
.rc-cell {
  position: relative;
  display: block;
  box-sizing: border-box;
  border: 1px solid rgba(111, 245, 238, 0.5);
  border-radius: 6%;
  background: rgba(4, 12, 24, 0.6);
  box-shadow: 0 0 6px rgba(0, 191, 243, 0.4), inset 0 0 10px rgba(0, 191, 243, 0.14);
}

/* hovered square: its edges light right up */
.rc-cell {
  transition: border-color 180ms ease, box-shadow 180ms ease, background 180ms ease;
}

.home-v2 .rc-cell:hover {
  border-color: var(--home-holo);
  background: rgba(111, 245, 238, 0.08);
  box-shadow: 0 0 18px rgba(111, 245, 238, 0.85), inset 0 0 18px rgba(111, 245, 238, 0.35);
}

/* light running across the squares in waves */
.rc-cell::after {
  content: "";
  position: absolute;
  inset: -1px;
  border: 1px solid var(--home-holo);
  border-radius: inherit;
  box-shadow: 0 0 14px rgba(111, 245, 238, 0.7), inset 0 0 12px rgba(111, 245, 238, 0.22);
  opacity: 0;
  pointer-events: none;
  animation: rc-wave 4.2s ease-in-out infinite;
  animation-delay: var(--rc-wave, 0s);
}

@keyframes rc-wave {
  0%,
  60%,
  100% {
    opacity: 0;
  }
  30% {
    opacity: 0.85;
  }
}

/* the centre square of each face: a link that presses in on hover */
.home-v2 .rc-link {
  border-color: rgba(111, 245, 238, 0.95);
  cursor: pointer;
  box-shadow: 0 0 10px rgba(111, 245, 238, 0.6), inset 0 0 14px rgba(111, 245, 238, 0.2);
  transition: transform 220ms cubic-bezier(0.3, 0, 0.2, 1), box-shadow 220ms ease, background 220ms ease;
}

.home-v2 .rc-link:hover,
.home-v2 .rc-link:focus-visible {
  outline: none;
  background: rgba(111, 245, 238, 0.14);
  /* pressed in: a deep inner glow and its name sinks a little. The square
     itself keeps its size: shrinking it would slip it out from under the
     cursor at its edges, and the hover (and cursor) would flicker. */
  box-shadow: 0 0 22px rgba(111, 245, 238, 0.9), inset 0 0 30px rgba(111, 245, 238, 0.6),
    inset 0 0 0 3px rgba(111, 245, 238, 0.25);
}

.home-v2 .rc-link:hover .rc-link-text,
.home-v2 .rc-link:focus-visible .rc-link-text {
  transform: scale(0.92);
}

.home-v2 .rc-link:active {
  box-shadow: 0 0 26px rgba(111, 245, 238, 1), inset 0 0 40px rgba(111, 245, 238, 0.8),
    inset 0 0 0 5px rgba(111, 245, 238, 0.35);
}

.home-v2 .rc-link:focus:not(:focus-visible) {
  outline: none;
}

/* the link's name, flat on the face over its centre square; big enough to
   read, so longer names spill across the middle row */
.rc-link-text {
  position: relative;
  z-index: 2;
  padding-left: 0.1em;
  color: #effdff;
  /* squared-off display face, in the cube's light */
  font: 600 calc(var(--rc-size) * 0.05) / 1 "Orbitron", var(--home-font);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  white-space: nowrap;
  text-shadow: 0 0 3px rgba(0, 0, 0, 0.7), 0 0 10px rgba(111, 245, 238, 0.85), 0 0 22px rgba(0, 191, 243, 0.5);
  pointer-events: none;
  transition: transform 220ms cubic-bezier(0.3, 0, 0.2, 1);
}

.home-v2 .rc-link,
.home-v2 .rc-link:hover,
.home-v2 .rc-link:focus {
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: visible;
  text-decoration: none;
}

/* --- holograms: line art over the whole face while it's looked at ------ */
.rc-holo {
  position: absolute;
  inset: 0;
  z-index: 1;
  opacity: 0;
  pointer-events: none;
  transition: opacity 250ms ease;
}

.rc-face.is-active .rc-holo {
  opacity: 1;
  animation: holo-in 520ms ease-out both;
}

/* projected in: a flickering sweep from the middle out */
@keyframes holo-in {
  0% {
    opacity: 0;
    clip-path: inset(50% 0 50% 0);
  }
  35% {
    opacity: 1;
  }
  45% {
    opacity: 0.45;
  }
  60% {
    opacity: 1;
    clip-path: inset(0 0 0 0);
  }
  100% {
    opacity: 1;
    clip-path: inset(0 0 0 0);
  }
}

/* scan lines over the hologram */
.rc-holo::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(0deg, rgba(111, 245, 238, 0.07) 0 1px, transparent 1px 4px);
}

.holo-art {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  filter: drop-shadow(0 0 3px rgba(111, 245, 238, 0.75));
}

.holo-line {
  fill: none;
  stroke: var(--home-holo);
  stroke-width: 1;
  opacity: 0.85;
  vector-effect: non-scaling-stroke;
}

.holo-line.faint {
  opacity: 0.35;
}

/* a pulse of light running along a line */
.holo-flow {
  fill: none;
  stroke: #fff;
  stroke-width: 0.9;
  stroke-linecap: round;
  stroke-dasharray: 4 96;
  animation: holo-flow 2.4s linear infinite;
}

.holo-software .holo-flow {
  stroke-dasharray: 12 88;
  animation-duration: 2.4s;
}

.holo-pad {
  fill: #02070f;
  stroke: var(--home-holo);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}

.holo-radar-sweep {
  transform-origin: 50px 50px;
  animation: holo-spin 4s linear infinite;
}

@keyframes holo-flow {
  from {
    stroke-dashoffset: 100;
  }
  to {
    stroke-dashoffset: 0;
  }
}

.holo-node,
.holo-dot,
.holo-commit {
  fill: var(--home-holo);
}

.holo-node.twinkle {
  animation: holo-twinkle 2s ease-in-out infinite;
}

@keyframes holo-twinkle {
  50% {
    opacity: 0.35;
  }
}

.holo-pulse {
  fill: none;
  stroke: var(--home-holo);
  stroke-width: 0.5;
  transform-box: fill-box;
  transform-origin: center;
  animation: holo-pulse 2s ease-out infinite;
}

@keyframes holo-pulse {
  from {
    opacity: 1;
    transform: scale(0.5);
  }
  to {
    opacity: 0;
    transform: scale(4);
  }
}

.holo-dot {
  opacity: 0.75;
}

.holo-spin-slow {
  transform-origin: 50px 50px;
  animation: holo-spin 40s linear infinite;
}

@keyframes holo-spin {
  to {
    transform: rotate(360deg);
  }
}

.holo-stroke {
  fill: none;
  stroke: #fff;
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-dasharray: 120;
  animation: holo-draw 3.2s ease-in-out infinite;
}

.holo-stroke.thin {
  stroke: var(--home-holo);
  stroke-width: 0.8;
  animation-delay: 0.25s;
}

@keyframes holo-draw {
  0% {
    stroke-dashoffset: 120;
  }
  45%,
  70% {
    stroke-dashoffset: 0;
    opacity: 1;
  }
  100% {
    stroke-dashoffset: 0;
    opacity: 0;
  }
}

/* neon grid rows sliding toward the viewer, faster as they come closer */
.holo-grid-rows path {
  opacity: 0;
  animation: holo-grid 3s cubic-bezier(0.55, 0, 1, 0.6) infinite;
}

@keyframes holo-grid {
  0% {
    opacity: 0;
    transform: translateY(46px);
  }
  15% {
    opacity: 0.8;
  }
  100% {
    opacity: 0.8;
    transform: translateY(100px);
  }
}

.holo-commit {
  stroke: #02070f;
  stroke-width: 0.8;
}

/* picked: every edge lights up while the cube folds away into a dot */
.rc-scene.is-collapsing .rc-cell {
  border-color: var(--home-holo);
  box-shadow: 0 0 16px rgba(111, 245, 238, 0.9), inset 0 0 16px rgba(111, 245, 238, 0.4);
}

.rc-scene.is-collapsing .rc-cell::after {
  animation: none;
}

.rc-dot {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #effffe;
  box-shadow: 0 0 10px 3px var(--home-holo), 0 0 44px 14px rgba(0, 191, 243, 0.55);
  opacity: 0;
  transform: translate(-50%, -50%) scale(0.4);
  pointer-events: none;
}

.home-v2:has(.rc-scene.is-collapsing) .home-v2-base,
.home-v2:has(.rc-scene.is-collapsing) .home-v2-hints {
  opacity: 0;
  transition: opacity 600ms ease;
}

/* --- all colours ------------------------------------------------------ */
/* Every square has its own colour (--cell-hue, random per square) and the
   whole face turns through the spectrum, so each square keeps changing
   colour while staying different from its neighbours. Squares rise and
   sink on their own random timing (--rise-* set per square from script). Everything that moves is a transform or an
   opacity, which the graphics card handles without repainting; the faces
   stay flat layers (Safari needs that), so a square "rises" by growing and
   brightening. */
.home-v2.is-spectrum .rc-face {
  animation: rc-spectrum 9s linear infinite;
}

@keyframes rc-spectrum {
  from {
    filter: hue-rotate(0deg) saturate(1.5) brightness(1.1);
  }
  to {
    filter: hue-rotate(360deg) saturate(1.5) brightness(1.1);
  }
}

.home-v2.is-spectrum .rc-cell {
  border-color: hsl(var(--cell-hue, 183) 100% 68%);
  background: hsl(var(--cell-hue, 183) 90% 45% / 0.06);
  box-shadow: 0 0 12px hsl(var(--cell-hue, 183) 100% 58% / 0.75), 0 0 26px hsl(var(--cell-hue, 183) 100% 55% / 0.3),
    inset 0 0 14px hsl(var(--cell-hue, 183) 100% 60% / 0.35);
  animation: rc-rise var(--rise-dur, 2s) ease-in-out var(--rise-delay, 0s) infinite alternate;
}

/* mostly resting, now and then lifting right up */
@keyframes rc-rise {
  0%,
  35% {
    transform: scale(1);
  }
  100% {
    transform: scale(1.13);
  }
}

/* the extra glow of a raised square: drawn once, faded in as it rises */
.rc-cell-glow {
  display: none;
}

.home-v2.is-spectrum .rc-cell-glow {
  position: absolute;
  inset: -1px;
  display: block;
  border: 1px solid hsl(var(--cell-hue, 183) 100% 80%);
  border-radius: inherit;
  background: hsl(var(--cell-hue, 183) 100% 55% / 0.14);
  box-shadow: 0 0 30px hsl(var(--cell-hue, 183) 100% 60% / 0.95), 0 0 56px hsl(var(--cell-hue, 183) 100% 55% / 0.45),
    inset 0 0 22px hsl(var(--cell-hue, 183) 100% 65% / 0.45);
  opacity: 0;
  pointer-events: none;
  animation: rc-lift-glow var(--rise-dur, 2s) ease-in-out var(--rise-delay, 0s) infinite alternate;
}

@keyframes rc-lift-glow {
  0%,
  35% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}

/* the light waves across the squares take each square's colour */
.home-v2.is-spectrum .rc-cell::after {
  border-color: hsl(var(--cell-hue, 183) 100% 75%);
  box-shadow: 0 0 24px hsl(var(--cell-hue, 183) 100% 60%), inset 0 0 18px hsl(var(--cell-hue, 183) 100% 60% / 0.4);
  animation-duration: 2.6s;
}

.home-v2.is-spectrum .rc-link {
  border-color: hsl(var(--cell-hue, 183) 100% 75%);
}

/* hold a square still under the mouse, so it doesn't slip away */
.home-v2.is-spectrum .rc-cell:hover,
.home-v2.is-spectrum .rc-cell:hover .rc-cell-glow {
  animation-play-state: paused;
}

.home-v2.is-spectrum .rc-link-text {
  text-shadow: 0 0 3px rgba(0, 0, 0, 0.8), 0 0 12px hsl(var(--cell-hue, 183) 100% 65%), 0 0 26px hsl(var(--cell-hue, 183) 100% 55% / 0.7);
}

/* the folding pick: every edge flares in its own colour */
.home-v2.is-spectrum .rc-scene.is-collapsing .rc-cell {
  border-color: hsl(var(--cell-hue, 183) 100% 75%);
}

/* the switch itself: bottom left, a black swatch and a spectrum swatch */
/* the colour switch shares the ui-toggle look (UiVersionToggle.css), and its
   spot, bottom right */
.colour-toggle.is-spectrum .ui-toggle-thumb {
  transform: translateX(100%);
}

.colour-toggle .ui-toggle-option {
  display: flex;
  align-items: center;
  justify-content: center;
  border: 0;
  background: none;
  cursor: pointer;
}

.colour-swatch {
  display: block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  transition: box-shadow 250ms ease, opacity 250ms ease;
}

.colour-swatch.is-cyan {
  background: #000;
  box-shadow: 0 0 0 1px rgba(111, 245, 238, 0.7);
}

.colour-swatch.is-spectrum {
  background: conic-gradient(#ff4d6d, #ffb84d, #f5ff4d, #4dff88, #4de8ff, #6d7bff, #d44dff, #ff4d6d);
}

.colour-toggle .ui-toggle-option:not(.is-active) .colour-swatch {
  opacity: 0.55;
}

.colour-toggle .ui-toggle-option.is-active .colour-swatch.is-spectrum {
  box-shadow: 0 0 10px rgba(255, 255, 255, 0.5);
}

/* --- platform ------------------------------------------------------- */
.home-v2-base {
  position: relative;
  width: calc(var(--rc-size) * 1.7);
  margin-top: calc(var(--rc-size) * -0.28);
}

.home-v2-platform {
  width: 100%;
}

.home-v2-shadow {
  position: absolute;
  z-index: 1;
  left: 30%;
  width: 40%;
  top: 50%;
  height: 18%;
  border-radius: 50%;
  background: radial-gradient(closest-side, rgba(0, 0, 0, 0.85), transparent);
  transform: translateY(-50%);
  animation: home-shadow 6s ease-in-out infinite;
}

/* in step with the bob: fainter as the cube rises */
@keyframes home-shadow {
  0%,
  100% {
    opacity: 0.85;
  }
  50% {
    opacity: 0.55;
  }
}

/* --- hints ---------------------------------------------------------- */
.home-v2-hints {
  position: absolute;
  z-index: 2;
  left: 50%;
  bottom: 30px;
  transform: translateX(-50%);
}

.home-v2 .home-v2-hint {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0;
  padding: 9px 16px;
  border: 1px solid rgba(111, 245, 238, 0.35);
  border-radius: 999px;
  background: rgba(3, 10, 20, 0.7);
  color: var(--home-holo);
  font: 600 11px/1 var(--home-font);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  white-space: nowrap;
  animation: home-fade-in 600ms ease-out 2.4s both;
}

.home-v2 .home-v2-hint:not(.is-button) {
  pointer-events: none;
}

.home-v2 .home-v2-hint.is-button {
  cursor: pointer;
}

.home-v2-hint-icon {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px rgba(111, 245, 238, 0.25);
  animation: home-hint-drag 1.8s ease-in-out infinite;
}

.home-v2-hint-icon.is-phone {
  width: 9px;
  height: 15px;
  border: 1.5px solid currentColor;
  border-radius: 3px;
  background: none;
  box-shadow: none;
  animation: home-hint-tilt 2.4s ease-in-out infinite;
}

@keyframes home-hint-drag {
  0%,
  100% {
    transform: translateX(-5px);
  }
  50% {
    transform: translateX(5px);
  }
}

@keyframes home-hint-tilt {
  0%,
  100% {
    transform: rotate(-18deg);
  }
  50% {
    transform: rotate(18deg);
  }
}

/* --- phones ----------------------------------------------------------- */
@media (max-width: 700px) {
  .home-v2 {
    --rc-size: min(54vw, 250px);
  }

  .home-v2-header {
    padding-top: 44px;
  }

  .home-v2 .home-v2-name {
    font-size: 17px;
    letter-spacing: 0.42em;
    padding-left: 0.42em;
  }

  .home-v2-stage {
    padding-bottom: 90px;
  }

  .home-v2-base {
    margin-top: calc(var(--rc-size) * -0.12);
  }


  /* clear of the UI version toggle in the corner */
  .home-v2-hints {
    bottom: 74px;
  }

  /* names a touch larger on the smaller cube, so they stay crisp */
  .rc-link-text {
    font-size: calc(var(--rc-size) * 0.058);
  }

  .home-v2 .home-v2-hint {
    padding: 8px 14px;
    font-size: 10px;
    letter-spacing: 0.12em;
  }
}

@media (prefers-reduced-motion: reduce) {
  .home-v2 *,
  .home-v2 *::before,
  .home-v2 *::after {
    animation: none !important;
  }

  /* all colours without the motion: each square simply keeps its colour */

  .flash-letter {
    opacity: 1;
  }
}
`, "",{"version":3,"sources":["webpack://./src/pages/Home/Home.css"],"names":[],"mappings":"AAAA;;;0EAG0E;AAC1E;oDACoD;AACpD;;EAEE,YAAY;EACZ,gBAAgB;EAChB,yBAAyB;AAC3B;;AAEA;EACE,eAAe;EACf,QAAQ;EACR,gBAAgB;AAClB;;AAEA;EACE,6BAA6B;EAC7B,oBAAoB;EACpB,oBAAoB;EACpB,2DAA2D;EAC3D,eAAe;EACf,QAAQ;EACR,aAAa;EACb,sBAAsB;EACtB,mBAAmB;EACnB,uEAAuE;EACvE,cAAc;EACd,6BAA6B;EAC7B,gBAAgB;EAChB,kBAAkB;EAClB,mCAAmC;EACnC,wCAAwC;AAC1C;;AAEA,wEAAwE;AACxE;EACE,cAAc;EACd,iBAAiB;EACjB,kBAAkB;AACpB;;AAEA;EACE,SAAS;EACT,+DAA+D;EAC/D,oBAAoB;EACpB,cAAc;EACd,uDAAuD;EACvD,sBAAsB;EACtB,mBAAmB;AACrB;;AAEA;EACE,qBAAqB;EACrB,UAAU;EACV;0EACwE;EACxE;;+DAE6D;AAC/D;;AAEA;EACE,qBAAqB;EACrB,YAAY;AACd;;AAEA;EACE;;;IAGE,cAAc;IACd,6CAA6C;EAC/C;EACA;IACE,WAAW;IACX,gFAAgF;EAClF;AACF;;AAEA,8DAA8D;AAC9D;EACE;IACE,UAAU;EACZ;EACA;IACE,UAAU;IACV,WAAW;IACX,+CAA+C;EACjD;EACA;IACE,YAAY;EACd;EACA;IACE,UAAU;IACV,WAAW;IACX,6BAA6B;EAC/B;EACA;IACE,aAAa;EACf;EACA;IACE,UAAU;IACV,WAAW;IACX,+CAA+C;EACjD;EACA;IACE,UAAU;IACV,cAAc;IACd,6CAA6C;EAC/C;AACF;;AAEA;EACE,gBAAgB;EAChB,mBAAmB;EACnB,uBAAuB;EACvB,iCAAiC;EACjC,qBAAqB;EACrB,yBAAyB;EACzB,gDAAgD;AAClD;;AAEA;EACE;IACE,UAAU;IACV,0BAA0B;EAC5B;EACA;IACE,UAAU;IACV,eAAe;EACjB;AACF;;AAEA,yEAAyE;AACzE;EACE,cAAc;EACd,aAAa;EACb,aAAa;EACb,sBAAsB;EACtB,mBAAmB;EACnB,uBAAuB;EACvB,oBAAoB;AACtB;;AAEA;EACE,kBAAkB;EAClB,UAAU;EACV,2CAA2C;AAC7C;;AAEA;EACE;;IAEE,wBAAwB;EAC1B;EACA;IACE,4BAA4B;EAC9B;AACF;;AAEA,qEAAqE;AACrE;EACE,kBAAkB;EAClB,aAAa;EACb,mBAAmB;EACnB,kCAAkC;EAClC,mCAAmC;EACnC,mBAAmB;EACnB,YAAY;EACZ,kBAAkB;EAClB,iBAAiB;EACjB,yBAAyB;AAC3B;;AAEA;EACE,gBAAgB;AAClB;;AAEA;EACE,qBAAqB;EACrB,sBAAsB;EACtB,4BAA4B;AAC9B;;AAEA;EACE,mCAAmC;EACnC,kBAAkB;EAClB,WAAW;EACX,YAAY;EACZ,4BAA4B;EAC5B,sBAAsB;AACxB;;AAEA;EACE,kBAAkB;EAClB,QAAQ;EACR,aAAa;EACb,mEAAmE;EACnE,gDAAgD;EAChD,6CAA6C;EAC7C,OAAO;EACP,WAAW;EACX,sBAAsB;EACtB,+BAA+B;EAC/B,qDAAqD;EACrD,2BAA2B;EAC3B,mCAAmC;EACnC;;sCAEoC;EACpC,qBAAqB;AACvB;;AAEA,wDAAwD;AACxD;EACE,kBAAkB;EAClB,cAAc;EACd,sBAAsB;EACtB,0CAA0C;EAC1C,iBAAiB;EACjB,gCAAgC;EAChC,kFAAkF;AACpF;;AAEA,6CAA6C;AAC7C;EACE,iFAAiF;AACnF;;AAEA;EACE,8BAA8B;EAC9B,qCAAqC;EACrC,wFAAwF;AAC1F;;AAEA,8CAA8C;AAC9C;EACE,WAAW;EACX,kBAAkB;EAClB,WAAW;EACX,kCAAkC;EAClC,sBAAsB;EACtB,uFAAuF;EACvF,UAAU;EACV,oBAAoB;EACpB,4CAA4C;EAC5C,mCAAmC;AACrC;;AAEA;EACE;;;IAGE,UAAU;EACZ;EACA;IACE,aAAa;EACf;AACF;;AAEA,oEAAoE;AACpE;EACE,uCAAuC;EACvC,eAAe;EACf,sFAAsF;EACtF,sGAAsG;AACxG;;AAEA;;EAEE,aAAa;EACb,qCAAqC;EACrC;;qEAEmE;EACnE;6CAC2C;AAC7C;;AAEA;;EAEE,sBAAsB;AACxB;;AAEA;EACE;6CAC2C;AAC7C;;AAEA;EACE,aAAa;AACf;;AAEA;sDACsD;AACtD;EACE,kBAAkB;EAClB,UAAU;EACV,mBAAmB;EACnB,cAAc;EACd,kDAAkD;EAClD,sEAAsE;EACtE,qBAAqB;EACrB,yBAAyB;EACzB,mBAAmB;EACnB,4GAA4G;EAC5G,oBAAoB;EACpB,wDAAwD;AAC1D;;AAEA;;;EAGE,aAAa;EACb,mBAAmB;EACnB,uBAAuB;EACvB,iBAAiB;EACjB,qBAAqB;AACvB;;AAEA,4EAA4E;AAC5E;EACE,kBAAkB;EAClB,QAAQ;EACR,UAAU;EACV,UAAU;EACV,oBAAoB;EACpB,8BAA8B;AAChC;;AAEA;EACE,UAAU;EACV,sCAAsC;AACxC;;AAEA,yDAAyD;AACzD;EACE;IACE,UAAU;IACV,6BAA6B;EAC/B;EACA;IACE,UAAU;EACZ;EACA;IACE,aAAa;EACf;EACA;IACE,UAAU;IACV,yBAAyB;EAC3B;EACA;IACE,UAAU;IACV,yBAAyB;EAC3B;AACF;;AAEA,iCAAiC;AACjC;EACE,WAAW;EACX,kBAAkB;EAClB,QAAQ;EACR,iGAAiG;AACnG;;AAEA;EACE,kBAAkB;EAClB,QAAQ;EACR,WAAW;EACX,YAAY;EACZ,iBAAiB;EACjB,sDAAsD;AACxD;;AAEA;EACE,UAAU;EACV,wBAAwB;EACxB,eAAe;EACf,aAAa;EACb,iCAAiC;AACnC;;AAEA;EACE,aAAa;AACf;;AAEA,0CAA0C;AAC1C;EACE,UAAU;EACV,YAAY;EACZ,iBAAiB;EACjB,qBAAqB;EACrB,sBAAsB;EACtB,yCAAyC;AAC3C;;AAEA;EACE,uBAAuB;EACvB,wBAAwB;AAC1B;;AAEA;EACE,aAAa;EACb,wBAAwB;EACxB,eAAe;EACf,iCAAiC;AACnC;;AAEA;EACE,2BAA2B;EAC3B,uCAAuC;AACzC;;AAEA;EACE;IACE,sBAAsB;EACxB;EACA;IACE,oBAAoB;EACtB;AACF;;AAEA;;;EAGE,sBAAsB;AACxB;;AAEA;EACE,+CAA+C;AACjD;;AAEA;EACE;IACE,aAAa;EACf;AACF;;AAEA;EACE,UAAU;EACV,wBAAwB;EACxB,iBAAiB;EACjB,uBAAuB;EACvB,wBAAwB;EACxB,0CAA0C;AAC5C;;AAEA;EACE;IACE,UAAU;IACV,qBAAqB;EACvB;EACA;IACE,UAAU;IACV,mBAAmB;EACrB;AACF;;AAEA;EACE,aAAa;AACf;;AAEA;EACE,2BAA2B;EAC3B,wCAAwC;AAC1C;;AAEA;EACE;IACE,yBAAyB;EAC3B;AACF;;AAEA;EACE,UAAU;EACV,YAAY;EACZ,iBAAiB;EACjB,qBAAqB;EACrB,qBAAqB;EACrB,8CAA8C;AAChD;;AAEA;EACE,wBAAwB;EACxB,iBAAiB;EACjB,sBAAsB;AACxB;;AAEA;EACE;IACE,sBAAsB;EACxB;EACA;;IAEE,oBAAoB;IACpB,UAAU;EACZ;EACA;IACE,oBAAoB;IACpB,UAAU;EACZ;AACF;;AAEA,yEAAyE;AACzE;EACE,UAAU;EACV,8DAA8D;AAChE;;AAEA;EACE;IACE,UAAU;IACV,2BAA2B;EAC7B;EACA;IACE,YAAY;EACd;EACA;IACE,YAAY;IACZ,4BAA4B;EAC9B;AACF;;AAEA;EACE,eAAe;EACf,iBAAiB;AACnB;;AAEA,sEAAsE;AACtE;EACE,8BAA8B;EAC9B,sFAAsF;AACxF;;AAEA;EACE,eAAe;AACjB;;AAEA;EACE,kBAAkB;EAClB,SAAS;EACT,QAAQ;EACR,WAAW;EACX,YAAY;EACZ,kBAAkB;EAClB,mBAAmB;EACnB,gFAAgF;EAChF,UAAU;EACV,2CAA2C;EAC3C,oBAAoB;AACtB;;AAEA;;EAEE,UAAU;EACV,8BAA8B;AAChC;;AAEA,2EAA2E;AAC3E;;;;;;iBAMiB;AACjB;EACE,yCAAyC;AAC3C;;AAEA;EACE;IACE,sDAAsD;EACxD;EACA;IACE,wDAAwD;EAC1D;AACF;;AAEA;EACE,gDAAgD;EAChD,oDAAoD;EACpD;4DAC0D;EAC1D,2FAA2F;AAC7F;;AAEA,kDAAkD;AAClD;EACE;;IAEE,mBAAmB;EACrB;EACA;IACE,sBAAsB;EACxB;AACF;;AAEA,wEAAwE;AACxE;EACE,aAAa;AACf;;AAEA;EACE,kBAAkB;EAClB,WAAW;EACX,cAAc;EACd,oDAAoD;EACpD,sBAAsB;EACtB,qDAAqD;EACrD;4DAC0D;EAC1D,UAAU;EACV,oBAAoB;EACpB,gGAAgG;AAClG;;AAEA;EACE;;IAEE,UAAU;EACZ;EACA;IACE,UAAU;EACZ;AACF;;AAEA,iEAAiE;AACjE;EACE,gDAAgD;EAChD,gHAAgH;EAChH,wBAAwB;AAC1B;;AAEA;EACE,gDAAgD;AAClD;;AAEA,iEAAiE;AACjE;;EAEE,4BAA4B;AAC9B;;AAEA;EACE,uIAAuI;AACzI;;AAEA,0DAA0D;AAC1D;EACE,gDAAgD;AAClD;;AAEA,yEAAyE;AACzE;uBACuB;AACvB;EACE,2BAA2B;AAC7B;;AAEA;EACE,aAAa;EACb,mBAAmB;EACnB,uBAAuB;EACvB,SAAS;EACT,gBAAgB;EAChB,eAAe;AACjB;;AAEA;EACE,cAAc;EACd,WAAW;EACX,YAAY;EACZ,kBAAkB;EAClB,qDAAqD;AACvD;;AAEA;EACE,gBAAgB;EAChB,8CAA8C;AAChD;;AAEA;EACE,kGAAkG;AACpG;;AAEA;EACE,aAAa;AACf;;AAEA;EACE,6CAA6C;AAC/C;;AAEA,yEAAyE;AACzE;EACE,kBAAkB;EAClB,iCAAiC;EACjC,wCAAwC;AAC1C;;AAEA;EACE,WAAW;AACb;;AAEA;EACE,kBAAkB;EAClB,UAAU;EACV,SAAS;EACT,UAAU;EACV,QAAQ;EACR,WAAW;EACX,kBAAkB;EAClB,2EAA2E;EAC3E,2BAA2B;EAC3B,8CAA8C;AAChD;;AAEA,oDAAoD;AACpD;EACE;;IAEE,aAAa;EACf;EACA;IACE,aAAa;EACf;AACF;;AAEA,yEAAyE;AACzE;EACE,kBAAkB;EAClB,UAAU;EACV,SAAS;EACT,YAAY;EACZ,2BAA2B;AAC7B;;AAEA;EACE,aAAa;EACb,mBAAmB;EACnB,SAAS;EACT,SAAS;EACT,iBAAiB;EACjB,2CAA2C;EAC3C,oBAAoB;EACpB,gCAAgC;EAChC,uBAAuB;EACvB,iCAAiC;EACjC,sBAAsB;EACtB,yBAAyB;EACzB,mBAAmB;EACnB,gDAAgD;AAClD;;AAEA;EACE,oBAAoB;AACtB;;AAEA;EACE,eAAe;AACjB;;AAEA;EACE,UAAU;EACV,WAAW;EACX,kBAAkB;EAClB,wBAAwB;EACxB,+CAA+C;EAC/C,mDAAmD;AACrD;;AAEA;EACE,UAAU;EACV,YAAY;EACZ,gCAAgC;EAChC,kBAAkB;EAClB,gBAAgB;EAChB,gBAAgB;EAChB,mDAAmD;AACrD;;AAEA;EACE;;IAEE,2BAA2B;EAC7B;EACA;IACE,0BAA0B;EAC5B;AACF;;AAEA;EACE;;IAEE,yBAAyB;EAC3B;EACA;IACE,wBAAwB;EAC1B;AACF;;AAEA,2EAA2E;AAC3E;EACE;IACE,2BAA2B;EAC7B;;EAEA;IACE,iBAAiB;EACnB;;EAEA;IACE,eAAe;IACf,sBAAsB;IACtB,oBAAoB;EACtB;;EAEA;IACE,oBAAoB;EACtB;;EAEA;IACE,wCAAwC;EAC1C;;;EAGA,iDAAiD;EACjD;IACE,YAAY;EACd;;EAEA,iEAAiE;EACjE;IACE,uCAAuC;EACzC;;EAEA;IACE,iBAAiB;IACjB,eAAe;IACf,sBAAsB;EACxB;AACF;;AAEA;EACE;;;IAGE,0BAA0B;EAC5B;;EAEA,wEAAwE;;EAExE;IACE,UAAU;EACZ;AACF","sourcesContent":["/* ---------------------------------------------------------------------\n   Homepage V2: a Rubik's cube of light over the holo platform, on the\n   same black as the About and Art pages.\n   --------------------------------------------------------------------- */\n/* nothing scrolls on this page: lock it, so turning the cube on a phone\n   never drags or pull-to-refreshes the page (iOS) */\nhtml.home-v2-html,\nbody.home-v2-body {\n  height: 100%;\n  overflow: hidden;\n  overscroll-behavior: none;\n}\n\nbody.home-v2-body {\n  position: fixed;\n  inset: 0;\n  background: #000;\n}\n\n.home-v2 {\n  --rc-size: min(38vmin, 340px);\n  --home-cyan: #00bff3;\n  --home-holo: #6ff5ee;\n  --home-font: \"DINWeb\", \"Lucida Grande\", verdana, sans-serif;\n  position: fixed;\n  inset: 0;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  background: linear-gradient(170deg, #03050a 0%, #000 55%, #02050b 100%);\n  color: #ccd4de;\n  font-family: var(--home-font);\n  overflow: hidden;\n  touch-action: none;\n  -webkit-font-smoothing: antialiased;\n  -webkit-tap-highlight-color: transparent;\n}\n\n/* --- name ---------------------------------------------------------- */\n.home-v2-header {\n  flex: 0 0 auto;\n  padding-top: 64px;\n  text-align: center;\n}\n\n.home-v2 .home-v2-name {\n  margin: 0;\n  /* the trailing letter-spacing would push the name off centre */\n  padding-left: 0.55em;\n  color: #dff4ff;\n  font: 600 clamp(18px, 2.4vw, 30px) / 1 var(--home-font);\n  letter-spacing: 0.55em;\n  white-space: nowrap;\n}\n\n.flash-letter {\n  display: inline-block;\n  opacity: 0;\n  /* strike on (delay set per letter), then, once every letter is lit, a\n     glow runs through the name from left to right, one letter at a time */\n  animation:\n    flash-on 1000ms linear var(--flash-delay, 0ms) both,\n    name-glow 5s ease-in-out var(--glow-delay, 2800ms) infinite;\n}\n\n.flash-space {\n  display: inline-block;\n  width: 0.5em;\n}\n\n@keyframes name-glow {\n  0%,\n  12%,\n  100% {\n    color: #dff4ff;\n    text-shadow: 0 0 10px rgba(0, 191, 243, 0.35);\n  }\n  5% {\n    color: #fff;\n    text-shadow: 0 0 12px #6ff5ee, 0 0 28px #00bff3, 0 0 44px rgba(0, 191, 243, 0.6);\n  }\n}\n\n/* a tube light striking: bright flash, flicker, then steady */\n@keyframes flash-on {\n  0% {\n    opacity: 0;\n  }\n  6% {\n    opacity: 1;\n    color: #fff;\n    text-shadow: 0 0 16px #6ff5ee, 0 0 34px #00bff3;\n  }\n  13% {\n    opacity: 0.1;\n  }\n  22% {\n    opacity: 1;\n    color: #fff;\n    text-shadow: 0 0 12px #6ff5ee;\n  }\n  30% {\n    opacity: 0.35;\n  }\n  40% {\n    opacity: 1;\n    color: #fff;\n    text-shadow: 0 0 14px #6ff5ee, 0 0 26px #00bff3;\n  }\n  100% {\n    opacity: 1;\n    color: #dff4ff;\n    text-shadow: 0 0 10px rgba(0, 191, 243, 0.35);\n  }\n}\n\n.home-v2 .home-v2-tagline {\n  margin: 16px 0 0;\n  padding-left: 0.4em;\n  color: var(--home-cyan);\n  font: 600 11px/1 var(--home-font);\n  letter-spacing: 0.4em;\n  text-transform: uppercase;\n  animation: home-fade-in 800ms ease-out 1.8s both;\n}\n\n@keyframes home-fade-in {\n  from {\n    opacity: 0;\n    transform: translateY(6px);\n  }\n  to {\n    opacity: 1;\n    transform: none;\n  }\n}\n\n/* --- stage ---------------------------------------------------------- */\n.home-v2-stage {\n  flex: 1 1 auto;\n  min-height: 0;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  padding-bottom: 56px;\n}\n\n.home-v2-float {\n  position: relative;\n  z-index: 1;\n  animation: home-bob 6s ease-in-out infinite;\n}\n\n@keyframes home-bob {\n  0%,\n  100% {\n    transform: translateY(0);\n  }\n  50% {\n    transform: translateY(-10px);\n  }\n}\n\n/* room around the cube to grab it, and for its corners as it turns */\n.rc-scene {\n  position: relative;\n  display: grid;\n  place-items: center;\n  width: calc(var(--rc-size) * 1.75);\n  height: calc(var(--rc-size) * 1.75);\n  perspective: 1500px;\n  cursor: grab;\n  touch-action: none;\n  user-select: none;\n  -webkit-user-select: none;\n}\n\n.rc-scene.is-dragging {\n  cursor: grabbing;\n}\n\n.rc-squash {\n  width: var(--rc-size);\n  height: var(--rc-size);\n  transform-style: preserve-3d;\n}\n\n.rc-cube {\n  --rc-half: calc(var(--rc-size) / 2);\n  position: relative;\n  width: 100%;\n  height: 100%;\n  transform-style: preserve-3d;\n  will-change: transform;\n}\n\n.rc-face {\n  position: absolute;\n  inset: 0;\n  display: grid;\n  /* equal squares even when a link's name is wider than its square */\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  grid-template-rows: repeat(3, minmax(0, 1fr));\n  gap: 4%;\n  padding: 4%;\n  box-sizing: border-box;\n  background: rgba(2, 7, 15, 0.9);\n  box-shadow: inset 0 0 0 1px rgba(111, 245, 238, 0.16);\n  backface-visibility: hidden;\n  -webkit-backface-visibility: hidden;\n  /* each face is one flat layer: Safari otherwise places its squares, name\n     and hologram in 3D on their own, so back faces show through and the\n     hologram can land over the name */\n  transform-style: flat;\n}\n\n/* every square: same dark colour, only its edges glow */\n.rc-cell {\n  position: relative;\n  display: block;\n  box-sizing: border-box;\n  border: 1px solid rgba(111, 245, 238, 0.5);\n  border-radius: 6%;\n  background: rgba(4, 12, 24, 0.6);\n  box-shadow: 0 0 6px rgba(0, 191, 243, 0.4), inset 0 0 10px rgba(0, 191, 243, 0.14);\n}\n\n/* hovered square: its edges light right up */\n.rc-cell {\n  transition: border-color 180ms ease, box-shadow 180ms ease, background 180ms ease;\n}\n\n.home-v2 .rc-cell:hover {\n  border-color: var(--home-holo);\n  background: rgba(111, 245, 238, 0.08);\n  box-shadow: 0 0 18px rgba(111, 245, 238, 0.85), inset 0 0 18px rgba(111, 245, 238, 0.35);\n}\n\n/* light running across the squares in waves */\n.rc-cell::after {\n  content: \"\";\n  position: absolute;\n  inset: -1px;\n  border: 1px solid var(--home-holo);\n  border-radius: inherit;\n  box-shadow: 0 0 14px rgba(111, 245, 238, 0.7), inset 0 0 12px rgba(111, 245, 238, 0.22);\n  opacity: 0;\n  pointer-events: none;\n  animation: rc-wave 4.2s ease-in-out infinite;\n  animation-delay: var(--rc-wave, 0s);\n}\n\n@keyframes rc-wave {\n  0%,\n  60%,\n  100% {\n    opacity: 0;\n  }\n  30% {\n    opacity: 0.85;\n  }\n}\n\n/* the centre square of each face: a link that presses in on hover */\n.home-v2 .rc-link {\n  border-color: rgba(111, 245, 238, 0.95);\n  cursor: pointer;\n  box-shadow: 0 0 10px rgba(111, 245, 238, 0.6), inset 0 0 14px rgba(111, 245, 238, 0.2);\n  transition: transform 220ms cubic-bezier(0.3, 0, 0.2, 1), box-shadow 220ms ease, background 220ms ease;\n}\n\n.home-v2 .rc-link:hover,\n.home-v2 .rc-link:focus-visible {\n  outline: none;\n  background: rgba(111, 245, 238, 0.14);\n  /* pressed in: a deep inner glow and its name sinks a little. The square\n     itself keeps its size: shrinking it would slip it out from under the\n     cursor at its edges, and the hover (and cursor) would flicker. */\n  box-shadow: 0 0 22px rgba(111, 245, 238, 0.9), inset 0 0 30px rgba(111, 245, 238, 0.6),\n    inset 0 0 0 3px rgba(111, 245, 238, 0.25);\n}\n\n.home-v2 .rc-link:hover .rc-link-text,\n.home-v2 .rc-link:focus-visible .rc-link-text {\n  transform: scale(0.92);\n}\n\n.home-v2 .rc-link:active {\n  box-shadow: 0 0 26px rgba(111, 245, 238, 1), inset 0 0 40px rgba(111, 245, 238, 0.8),\n    inset 0 0 0 5px rgba(111, 245, 238, 0.35);\n}\n\n.home-v2 .rc-link:focus:not(:focus-visible) {\n  outline: none;\n}\n\n/* the link's name, flat on the face over its centre square; big enough to\n   read, so longer names spill across the middle row */\n.rc-link-text {\n  position: relative;\n  z-index: 2;\n  padding-left: 0.1em;\n  color: #effdff;\n  /* squared-off display face, in the cube's light */\n  font: 600 calc(var(--rc-size) * 0.05) / 1 \"Orbitron\", var(--home-font);\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n  white-space: nowrap;\n  text-shadow: 0 0 3px rgba(0, 0, 0, 0.7), 0 0 10px rgba(111, 245, 238, 0.85), 0 0 22px rgba(0, 191, 243, 0.5);\n  pointer-events: none;\n  transition: transform 220ms cubic-bezier(0.3, 0, 0.2, 1);\n}\n\n.home-v2 .rc-link,\n.home-v2 .rc-link:hover,\n.home-v2 .rc-link:focus {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  overflow: visible;\n  text-decoration: none;\n}\n\n/* --- holograms: line art over the whole face while it's looked at ------ */\n.rc-holo {\n  position: absolute;\n  inset: 0;\n  z-index: 1;\n  opacity: 0;\n  pointer-events: none;\n  transition: opacity 250ms ease;\n}\n\n.rc-face.is-active .rc-holo {\n  opacity: 1;\n  animation: holo-in 520ms ease-out both;\n}\n\n/* projected in: a flickering sweep from the middle out */\n@keyframes holo-in {\n  0% {\n    opacity: 0;\n    clip-path: inset(50% 0 50% 0);\n  }\n  35% {\n    opacity: 1;\n  }\n  45% {\n    opacity: 0.45;\n  }\n  60% {\n    opacity: 1;\n    clip-path: inset(0 0 0 0);\n  }\n  100% {\n    opacity: 1;\n    clip-path: inset(0 0 0 0);\n  }\n}\n\n/* scan lines over the hologram */\n.rc-holo::after {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  background: repeating-linear-gradient(0deg, rgba(111, 245, 238, 0.07) 0 1px, transparent 1px 4px);\n}\n\n.holo-art {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  overflow: visible;\n  filter: drop-shadow(0 0 3px rgba(111, 245, 238, 0.75));\n}\n\n.holo-line {\n  fill: none;\n  stroke: var(--home-holo);\n  stroke-width: 1;\n  opacity: 0.85;\n  vector-effect: non-scaling-stroke;\n}\n\n.holo-line.faint {\n  opacity: 0.35;\n}\n\n/* a pulse of light running along a line */\n.holo-flow {\n  fill: none;\n  stroke: #fff;\n  stroke-width: 0.9;\n  stroke-linecap: round;\n  stroke-dasharray: 4 96;\n  animation: holo-flow 2.4s linear infinite;\n}\n\n.holo-software .holo-flow {\n  stroke-dasharray: 12 88;\n  animation-duration: 2.4s;\n}\n\n.holo-pad {\n  fill: #02070f;\n  stroke: var(--home-holo);\n  stroke-width: 1;\n  vector-effect: non-scaling-stroke;\n}\n\n.holo-radar-sweep {\n  transform-origin: 50px 50px;\n  animation: holo-spin 4s linear infinite;\n}\n\n@keyframes holo-flow {\n  from {\n    stroke-dashoffset: 100;\n  }\n  to {\n    stroke-dashoffset: 0;\n  }\n}\n\n.holo-node,\n.holo-dot,\n.holo-commit {\n  fill: var(--home-holo);\n}\n\n.holo-node.twinkle {\n  animation: holo-twinkle 2s ease-in-out infinite;\n}\n\n@keyframes holo-twinkle {\n  50% {\n    opacity: 0.35;\n  }\n}\n\n.holo-pulse {\n  fill: none;\n  stroke: var(--home-holo);\n  stroke-width: 0.5;\n  transform-box: fill-box;\n  transform-origin: center;\n  animation: holo-pulse 2s ease-out infinite;\n}\n\n@keyframes holo-pulse {\n  from {\n    opacity: 1;\n    transform: scale(0.5);\n  }\n  to {\n    opacity: 0;\n    transform: scale(4);\n  }\n}\n\n.holo-dot {\n  opacity: 0.75;\n}\n\n.holo-spin-slow {\n  transform-origin: 50px 50px;\n  animation: holo-spin 40s linear infinite;\n}\n\n@keyframes holo-spin {\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n.holo-stroke {\n  fill: none;\n  stroke: #fff;\n  stroke-width: 2.4;\n  stroke-linecap: round;\n  stroke-dasharray: 120;\n  animation: holo-draw 3.2s ease-in-out infinite;\n}\n\n.holo-stroke.thin {\n  stroke: var(--home-holo);\n  stroke-width: 0.8;\n  animation-delay: 0.25s;\n}\n\n@keyframes holo-draw {\n  0% {\n    stroke-dashoffset: 120;\n  }\n  45%,\n  70% {\n    stroke-dashoffset: 0;\n    opacity: 1;\n  }\n  100% {\n    stroke-dashoffset: 0;\n    opacity: 0;\n  }\n}\n\n/* neon grid rows sliding toward the viewer, faster as they come closer */\n.holo-grid-rows path {\n  opacity: 0;\n  animation: holo-grid 3s cubic-bezier(0.55, 0, 1, 0.6) infinite;\n}\n\n@keyframes holo-grid {\n  0% {\n    opacity: 0;\n    transform: translateY(46px);\n  }\n  15% {\n    opacity: 0.8;\n  }\n  100% {\n    opacity: 0.8;\n    transform: translateY(100px);\n  }\n}\n\n.holo-commit {\n  stroke: #02070f;\n  stroke-width: 0.8;\n}\n\n/* picked: every edge lights up while the cube folds away into a dot */\n.rc-scene.is-collapsing .rc-cell {\n  border-color: var(--home-holo);\n  box-shadow: 0 0 16px rgba(111, 245, 238, 0.9), inset 0 0 16px rgba(111, 245, 238, 0.4);\n}\n\n.rc-scene.is-collapsing .rc-cell::after {\n  animation: none;\n}\n\n.rc-dot {\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  width: 14px;\n  height: 14px;\n  border-radius: 50%;\n  background: #effffe;\n  box-shadow: 0 0 10px 3px var(--home-holo), 0 0 44px 14px rgba(0, 191, 243, 0.55);\n  opacity: 0;\n  transform: translate(-50%, -50%) scale(0.4);\n  pointer-events: none;\n}\n\n.home-v2:has(.rc-scene.is-collapsing) .home-v2-base,\n.home-v2:has(.rc-scene.is-collapsing) .home-v2-hints {\n  opacity: 0;\n  transition: opacity 600ms ease;\n}\n\n/* --- all colours ------------------------------------------------------ */\n/* Every square has its own colour (--cell-hue, random per square) and the\n   whole face turns through the spectrum, so each square keeps changing\n   colour while staying different from its neighbours. Squares rise and\n   sink on their own random timing (--rise-* set per square from script). Everything that moves is a transform or an\n   opacity, which the graphics card handles without repainting; the faces\n   stay flat layers (Safari needs that), so a square \"rises\" by growing and\n   brightening. */\n.home-v2.is-spectrum .rc-face {\n  animation: rc-spectrum 9s linear infinite;\n}\n\n@keyframes rc-spectrum {\n  from {\n    filter: hue-rotate(0deg) saturate(1.5) brightness(1.1);\n  }\n  to {\n    filter: hue-rotate(360deg) saturate(1.5) brightness(1.1);\n  }\n}\n\n.home-v2.is-spectrum .rc-cell {\n  border-color: hsl(var(--cell-hue, 183) 100% 68%);\n  background: hsl(var(--cell-hue, 183) 90% 45% / 0.06);\n  box-shadow: 0 0 12px hsl(var(--cell-hue, 183) 100% 58% / 0.75), 0 0 26px hsl(var(--cell-hue, 183) 100% 55% / 0.3),\n    inset 0 0 14px hsl(var(--cell-hue, 183) 100% 60% / 0.35);\n  animation: rc-rise var(--rise-dur, 2s) ease-in-out var(--rise-delay, 0s) infinite alternate;\n}\n\n/* mostly resting, now and then lifting right up */\n@keyframes rc-rise {\n  0%,\n  35% {\n    transform: scale(1);\n  }\n  100% {\n    transform: scale(1.13);\n  }\n}\n\n/* the extra glow of a raised square: drawn once, faded in as it rises */\n.rc-cell-glow {\n  display: none;\n}\n\n.home-v2.is-spectrum .rc-cell-glow {\n  position: absolute;\n  inset: -1px;\n  display: block;\n  border: 1px solid hsl(var(--cell-hue, 183) 100% 80%);\n  border-radius: inherit;\n  background: hsl(var(--cell-hue, 183) 100% 55% / 0.14);\n  box-shadow: 0 0 30px hsl(var(--cell-hue, 183) 100% 60% / 0.95), 0 0 56px hsl(var(--cell-hue, 183) 100% 55% / 0.45),\n    inset 0 0 22px hsl(var(--cell-hue, 183) 100% 65% / 0.45);\n  opacity: 0;\n  pointer-events: none;\n  animation: rc-lift-glow var(--rise-dur, 2s) ease-in-out var(--rise-delay, 0s) infinite alternate;\n}\n\n@keyframes rc-lift-glow {\n  0%,\n  35% {\n    opacity: 0;\n  }\n  100% {\n    opacity: 1;\n  }\n}\n\n/* the light waves across the squares take each square's colour */\n.home-v2.is-spectrum .rc-cell::after {\n  border-color: hsl(var(--cell-hue, 183) 100% 75%);\n  box-shadow: 0 0 24px hsl(var(--cell-hue, 183) 100% 60%), inset 0 0 18px hsl(var(--cell-hue, 183) 100% 60% / 0.4);\n  animation-duration: 2.6s;\n}\n\n.home-v2.is-spectrum .rc-link {\n  border-color: hsl(var(--cell-hue, 183) 100% 75%);\n}\n\n/* hold a square still under the mouse, so it doesn't slip away */\n.home-v2.is-spectrum .rc-cell:hover,\n.home-v2.is-spectrum .rc-cell:hover .rc-cell-glow {\n  animation-play-state: paused;\n}\n\n.home-v2.is-spectrum .rc-link-text {\n  text-shadow: 0 0 3px rgba(0, 0, 0, 0.8), 0 0 12px hsl(var(--cell-hue, 183) 100% 65%), 0 0 26px hsl(var(--cell-hue, 183) 100% 55% / 0.7);\n}\n\n/* the folding pick: every edge flares in its own colour */\n.home-v2.is-spectrum .rc-scene.is-collapsing .rc-cell {\n  border-color: hsl(var(--cell-hue, 183) 100% 75%);\n}\n\n/* the switch itself: bottom left, a black swatch and a spectrum swatch */\n/* the colour switch shares the ui-toggle look (UiVersionToggle.css), and its\n   spot, bottom right */\n.colour-toggle.is-spectrum .ui-toggle-thumb {\n  transform: translateX(100%);\n}\n\n.colour-toggle .ui-toggle-option {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border: 0;\n  background: none;\n  cursor: pointer;\n}\n\n.colour-swatch {\n  display: block;\n  width: 12px;\n  height: 12px;\n  border-radius: 50%;\n  transition: box-shadow 250ms ease, opacity 250ms ease;\n}\n\n.colour-swatch.is-cyan {\n  background: #000;\n  box-shadow: 0 0 0 1px rgba(111, 245, 238, 0.7);\n}\n\n.colour-swatch.is-spectrum {\n  background: conic-gradient(#ff4d6d, #ffb84d, #f5ff4d, #4dff88, #4de8ff, #6d7bff, #d44dff, #ff4d6d);\n}\n\n.colour-toggle .ui-toggle-option:not(.is-active) .colour-swatch {\n  opacity: 0.55;\n}\n\n.colour-toggle .ui-toggle-option.is-active .colour-swatch.is-spectrum {\n  box-shadow: 0 0 10px rgba(255, 255, 255, 0.5);\n}\n\n/* --- platform ------------------------------------------------------- */\n.home-v2-base {\n  position: relative;\n  width: calc(var(--rc-size) * 1.7);\n  margin-top: calc(var(--rc-size) * -0.28);\n}\n\n.home-v2-platform {\n  width: 100%;\n}\n\n.home-v2-shadow {\n  position: absolute;\n  z-index: 1;\n  left: 30%;\n  width: 40%;\n  top: 50%;\n  height: 18%;\n  border-radius: 50%;\n  background: radial-gradient(closest-side, rgba(0, 0, 0, 0.85), transparent);\n  transform: translateY(-50%);\n  animation: home-shadow 6s ease-in-out infinite;\n}\n\n/* in step with the bob: fainter as the cube rises */\n@keyframes home-shadow {\n  0%,\n  100% {\n    opacity: 0.85;\n  }\n  50% {\n    opacity: 0.55;\n  }\n}\n\n/* --- hints ---------------------------------------------------------- */\n.home-v2-hints {\n  position: absolute;\n  z-index: 2;\n  left: 50%;\n  bottom: 30px;\n  transform: translateX(-50%);\n}\n\n.home-v2 .home-v2-hint {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin: 0;\n  padding: 9px 16px;\n  border: 1px solid rgba(111, 245, 238, 0.35);\n  border-radius: 999px;\n  background: rgba(3, 10, 20, 0.7);\n  color: var(--home-holo);\n  font: 600 11px/1 var(--home-font);\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n  white-space: nowrap;\n  animation: home-fade-in 600ms ease-out 2.4s both;\n}\n\n.home-v2 .home-v2-hint:not(.is-button) {\n  pointer-events: none;\n}\n\n.home-v2 .home-v2-hint.is-button {\n  cursor: pointer;\n}\n\n.home-v2-hint-icon {\n  width: 9px;\n  height: 9px;\n  border-radius: 50%;\n  background: currentColor;\n  box-shadow: 0 0 0 3px rgba(111, 245, 238, 0.25);\n  animation: home-hint-drag 1.8s ease-in-out infinite;\n}\n\n.home-v2-hint-icon.is-phone {\n  width: 9px;\n  height: 15px;\n  border: 1.5px solid currentColor;\n  border-radius: 3px;\n  background: none;\n  box-shadow: none;\n  animation: home-hint-tilt 2.4s ease-in-out infinite;\n}\n\n@keyframes home-hint-drag {\n  0%,\n  100% {\n    transform: translateX(-5px);\n  }\n  50% {\n    transform: translateX(5px);\n  }\n}\n\n@keyframes home-hint-tilt {\n  0%,\n  100% {\n    transform: rotate(-18deg);\n  }\n  50% {\n    transform: rotate(18deg);\n  }\n}\n\n/* --- phones ----------------------------------------------------------- */\n@media (max-width: 700px) {\n  .home-v2 {\n    --rc-size: min(54vw, 250px);\n  }\n\n  .home-v2-header {\n    padding-top: 44px;\n  }\n\n  .home-v2 .home-v2-name {\n    font-size: 17px;\n    letter-spacing: 0.42em;\n    padding-left: 0.42em;\n  }\n\n  .home-v2-stage {\n    padding-bottom: 90px;\n  }\n\n  .home-v2-base {\n    margin-top: calc(var(--rc-size) * -0.12);\n  }\n\n\n  /* clear of the UI version toggle in the corner */\n  .home-v2-hints {\n    bottom: 74px;\n  }\n\n  /* names a touch larger on the smaller cube, so they stay crisp */\n  .rc-link-text {\n    font-size: calc(var(--rc-size) * 0.058);\n  }\n\n  .home-v2 .home-v2-hint {\n    padding: 8px 14px;\n    font-size: 10px;\n    letter-spacing: 0.12em;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .home-v2 *,\n  .home-v2 *::before,\n  .home-v2 *::after {\n    animation: none !important;\n  }\n\n  /* all colours without the motion: each square simply keeps its colour */\n\n  .flash-letter {\n    opacity: 1;\n  }\n}\n"],"sourceRoot":""}]);
